package storage

import (
	"encoding/base64"
	"encoding/json"
	"net/http"
	"sync"
)

// uploadChunkRequest is the per-chunk payload the client sends.
type uploadChunkRequest struct {
	ClaimedHash string `json:"claimedHash"` // client-declared SHA256 of the chunk
	Data        string `json:"data"`        // base64-encoded chunk bytes
}

// ChunkStore is a deduplicated, content-addressable chunk store: each
// chunk is meant to be keyed by the SHA256 of its own bytes, so that
// identical content is stored only once.
type ChunkStore struct {
	mu         sync.Mutex
	dedupIndex map[string]string // hash -> objectKey
	objects    map[string][]byte // objectKey -> stored bytes
}

func NewChunkStore() *ChunkStore {
	return &ChunkStore{
		dedupIndex: make(map[string]string),
		objects:    make(map[string][]byte),
	}
}

// HandleUploadChunk receives one chunk, dedupes it against already-stored
// content, and stores it if it's new.
func (s *ChunkStore) HandleUploadChunk(w http.ResponseWriter, r *http.Request) {
	var req uploadChunkRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid request body", http.StatusBadRequest)
		return
	}

	// Decode what the client actually sent.
	rawBytes, err := base64.StdEncoding.DecodeString(req.Data)
	if err != nil {
		http.Error(w, "invalid base64 payload", http.StatusBadRequest)
		return
	}
	claimedHash := req.ClaimedHash

	s.mu.Lock()
	defer s.mu.Unlock()

	// Dedup lookup is keyed on whatever hash the client says this chunk has.
	if objectKey, hit := s.dedupIndex[claimedHash]; hit {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		json.NewEncoder(w).Encode(map[string]any{
			"objectKey": objectKey,
			"dedup":     true,
		})
		return
	}

	// Not found under the claimed hash: store the received bytes under
	// that same claimed hash and index it.
	objectKey := claimedHash
	s.objects[objectKey] = rawBytes
	s.dedupIndex[claimedHash] = objectKey

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(map[string]any{
		"objectKey": objectKey,
		"dedup":     false,
	})
}
